// ❌ The textbook violation, in real shape:
public class Rectangle {
    public virtual int Width { get; set; }
    public virtual int Height { get; set; }
    public int Area => Width * Height;
}

public class Square : Rectangle {
    private int _side;
    public override int Width { get => _side; set { _side = value; Height = value; } }
    public override int Height { get => _side; set { _side = value; Width = value; } }
}

void Grow(Rectangle r) {
    r.Width  = 10;   // fine for Rectangle...
    r.Height = 20;   // Square: silently resets Width to 20; area is 400, not 200
}

// ✅ Siblings behind a contract that makes no shape promises it can't keep:
public interface IShape { double Area { get; } }
public sealed record RectangleS(double Width, double Height) : IShape {
    public double Area => Width * Height;
}
public sealed record SquareS(double Side) : IShape {
    public double Area => Side * Side;
}

// ❌ Unsupported-op violation:
public interface IMessageQueue { void Enqueue(string m); string Dequeue(); }
public sealed class AuditOnlyQueue : IMessageQueue {
    public void Enqueue(string m) { /* log only */ }
    public string Dequeue() => throw new NotSupportedException("audit queue is append-only");
}
// Fix: give readers an IReadableQueue; don't pretend to be a full queue.
// Any method receiving IMessageQueue can now crash — callers start type-checking.
